using Sem.Web.Core;
int passed = 0;
void Check(bool value, string name) { if (!value) throw new Exception(name); passed++; Console.WriteLine("PASS " + name); }
void Deny(Action action, string name) { var denied = false; try { action(); } catch (InvalidOperationException) { denied = true; } Check(denied, name); }
ManualNotificationPreview Preview(string subject = "<img src=x>", string body = "line1\nline2") => new("event", "event title", 2, subject, body, 2, new string('A', 64), "新しいメッセージがあります");
var state = new ManualNotificationComposerState();
Check(!state.NavigationBlocked && state.CanEdit, "empty composer permits navigation");
Deny(() => state.BeginSubmit(), "no submission before explicit preview");
state.Edit(" subject ", " body "); Check(state.NavigationBlocked, "unsent input blocks navigation");
state.BeginPreview(); Check(state.Busy && state.NavigationBlocked && !state.CanEdit, "preview operation locks input and navigation");
Deny(() => state.BeginPreview(), "duplicate preview rejected while busy");
Deny(() => state.DiscardDraft(), "cannot discard while preview in progress");
state.ShowPreview(Preview()); Check(!state.Busy && state.Preview is not null && !state.Confirmed, "preview does not imply confirmation");
Deny(() => state.BeginSubmit(), "preview alone cannot submit");
state.Confirm(true); state.Edit("changed", state.Body); Check(state.Preview is null && !state.Confirmed, "editing invalidates preview and confirmation");
state.BeginPreview(); state.PreviewFailed(); Check(!state.Busy && state.NavigationBlocked, "failed read preserves draft only");
state.BeginPreview(); state.ShowPreview(Preview()); state.Confirm(true);
var request = state.BeginSubmit();
Check(Guid.TryParseExact(request.RequestId, "D", out var guid) && guid.ToString("D") == request.RequestId, "submission allocates canonical lowercase operation ID");
Check(request.Subject == "<img src=x>" && request.Confirmed && request.PreviewFingerprint == Preview().Fingerprint, "request freezes displayed plain text and comparison");
Deny(() => state.BeginSubmit(), "rapid second submit cannot allocate another operation");
Deny(() => state.Edit("replacement", "replacement"), "in-flight draft immutable");
Deny(() => state.DiscardDraft(), "cannot discard in-flight request");
Deny(() => state.StartNew(), "cannot start new operation while in flight");
state.SubmissionUnknown(); Check(state.Uncertain && state.Pending == request && state.NavigationBlocked && !state.Busy, "unknown result keeps exact request and navigation lock");
Deny(() => state.DiscardDraft(), "cannot discard unknown request");
Deny(() => state.Edit("changed", "changed"), "unknown request cannot be edited");
var retry = state.BeginSubmit(); Check(ReferenceEquals(request, retry), "explicit retry reuses same immutable request instance");
state.SubmissionRejected(); Check(state.Uncertain && state.Pending == request && !state.CanEdit, "later 4xx does not disprove earlier unknown commit");
Deny(() => state.StartNew(), "rejected retry remains locked");
state.BeginSubmit();
Deny(() => state.SubmissionAccepted(new(Guid.NewGuid().ToString(), 2, 1)), "wrong operation response cannot unlock");
Deny(() => state.SubmissionAccepted(new(request.RequestId, 2, long.MaxValue)), "out-of-range acceptance time cannot unlock");
state.SubmissionUnknown(); Check(state.Pending == request, "malformed success retains request for safe replay");
state.BeginSubmit(); state.SubmissionAccepted(new(request.RequestId, 2, 1760000000, true));
Check(state.Accepted?.Replayed == true && state.Pending is null && !state.NavigationBlocked, "confirmed durable replay unlocks navigation");
Check(state.Subject == "" && state.Body == "" && state.Preview is null && !state.Confirmed, "successful save clears draft and approval");
Deny(() => state.BeginSubmit(), "accepted result cannot resubmit accidentally");
state.StartNew(); Check(state.Accepted is null && state.CanEdit && !state.NavigationBlocked, "new send requires explicit new composer action");
state.Edit("text", "body"); state.BeginPreview(); state.ShowPreview(Preview()); state.Confirm(true); state.BeginSubmit(); state.SubmissionRejected();
Check(state.Pending is null && state.Preview is null && !state.Confirmed && state.CanEdit, "first definite rejection requires fresh preview");
Check(state.Subject == "<img src=x>", "definite rejection preserves editable draft");
state.DiscardDraft(); Check(!state.NavigationBlocked && state.Subject.Length == 0 && state.Body.Length == 0, "explicit unsent discard clears only draft");
Console.WriteLine($"Manual notification composer: {passed} checks passed.");
